import{z as l,x as n,o as E,c as B,q as t,j as o,D as e,d as s,s as A,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"无谓损失的度量","description":"","frontmatter":{"title":"无谓损失的度量","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/deadweight-loss-measure.md","filePath":"econ/deadweight-loss-measure.md","lastUpdated":1791413859000}'),d={name:"econ/deadweight-loss-measure.md"};function p(D,a,h,m,c,_){const r=n("Mermaid");return E(),B("div",null,[a[2]||(a[2]=t('<h1 id="无谓损失的度量" tabindex="-1">无谓损失的度量 <a class="header-anchor" href="#无谓损失的度量" aria-label="Permalink to &quot;无谓损失的度量&quot;">​</a></h1><div class="epigraph"><p>税率翻倍，收入大约翻倍，被挤掉的互利大约翻两番——平方律是税制设计里最便宜的一条定理，也最常被忘记。</p><footer>—— 据 Harberger, The Measurement of Waste, AER 1964；Ramsey, A Contribution to the Theory of Taxation, EJ 1927 整理</footer></div><p><a href="/econ/tax-incidence-statutory">上一课</a>把楔子的矩形按弹性分了家：归宿是分配，落在谁身上另有答案。矩形之外还有三角形——被税挤掉的互利交易，买方、卖方、国库谁也不曾拿到。主干<a href="/econ/deadweight-loss">无谓损失</a>已把矩形与三角形分开；本课做度量：三角形怎么从弹性算出来、为什么随税率平方增长、边际与平均差多远，并接回 <a href="/econ/ramsey-optimal-commodity-tax">Ramsey 最优商品税</a>的一阶条件——Ramsey 规则就是把这些边际三角形拉平。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>从量税 \\(t\\) 使数量收缩 \\(\\Delta q\\)，局部近似下</p> \\[\\mathrm{DWL}\\approx \\tfrac12\\,t\\,\\Delta q \\;\\approx\\; \\tfrac12\\,\\Bigl(\\tfrac{t}{p}\\Bigr)^{2}\\, \\frac{\\varepsilon_D\\varepsilon_S}{\\varepsilon_D+\\varepsilon_S}\\,p q . \\]<p>缺口是把这条式子当成计算而非口号：税率从 10% 提到 20%，收入翻倍，三角形翻两番；「多征一元的效率成本是多少」与「这一税种平均多贵」是两个问题——前者随税率上升，后者是它的平均。Ramsey 问题的原形正是边际版：在多个税基上筹固定收入，把每一处的边际三角形对边际收入拉平。</p><h3 id="平方律的算术" tabindex="-1">平方律的算术 <a class="header-anchor" href="#平方律的算术" aria-label="Permalink to &quot;平方律的算术&quot;">​</a></h3><p>代入数字。需求弹性 \\(\\varepsilon_D=1\\)、供给充分时，\\(\\tau=10\\%\\) 的税，三角形约为税前支出的 \\(0.5\\%\\)，约为税收收入的 \\(5\\%\\)；\\(\\tau=20\\%\\) 时约为税收收入的 \\(10\\%\\)——绝对损失翻两番，收入只翻一番。两个 \\(10\\%\\) 的窄税几乎总比一个 \\(20\\%\\) 的税便宜：这是「宽基低税率」的全部效率算术，也是增值税把碎片优惠合并成单一税率的理由。</p><p><span class="marginnote">术语翻译：无谓损失就是「谁也没拿走的那部分损失」。税把买方卖方的钱收进国库是转移——钱换了主人还在；而被税吓退的交易本来能创造的互利，买方没得到、卖方没得到、国库也没得到，凭空消失。三角形量的是消失，矩形量的是转移。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Harberger 1964 的口径：在税后均衡点用可观测弹性估三角形，把各市场的小三角形加总，作为第一最佳附近的二次近似。这给出一台可操作的仪器：每讨论一次税改，先问楔子动多少、税基弹性多大，再按平方律报价。边际版：在 \\(\\tau\\) 处多筹一元，新增三角形约为 \\(\\tau\\,\\Delta q\\) 对新增收入的比，\\(\\tau\\) 越大越贵——<a href="/econ/redistribution-efficiency">再分配与效率代价</a>的「边际公共资金」在此有了度量口径。与 Ramsey 的分工：给定单一税基，按逆弹性分布楔子；给定多个税基，利用平方律把每个楔子都压低——两句话不矛盾，是同一二阶近似在不同约束下的投影。</p>',12)),(E(),o(i,null,{default:e(()=>[A(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20INC%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E7%9F%A9%E5%BD%A2%E6%8C%89%E5%BC%B9%E6%80%A7%E5%88%86%E5%AE%B6%22%5D%20--%3E%20TRI%5B%22%E4%B8%89%E8%A7%92%E5%BD%A2%20%C2%BD%20t%20%CE%94q%22%5D%0A%20%20TRI%20--%3E%20SQ%5B%22%E5%B9%B3%E6%96%B9%E5%BE%8B%3A%20%E2%88%9D%20t%C2%B2%20%C2%B7%20%CE%B5%20%C2%B7%20%E6%94%AF%E5%87%BA%22%5D%0A%20%20SQ%20--%3E%20MRG%5B%22%E8%BE%B9%E9%99%85%E4%B8%89%E8%A7%92%E5%BD%A2%E9%9A%8F%20%CF%84%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20MRG%20--%3E%20RAM%5B%22Ramsey%3A%20%E6%8B%89%E5%B9%B3%E5%90%84%E7%A8%8E%E5%9F%BA%E7%9A%84%E8%BE%B9%E9%99%85%E4%B8%89%E8%A7%92%E5%BD%A2%22%5D%0A%20%20TRI%20--%3E%20PIGOU%5B%22%E7%9F%AB%E6%AD%A3%E6%A5%94%E5%AD%90%E7%9A%84%E4%B8%89%E8%A7%92%E5%BD%A2%E6%98%AF%E6%A0%A1%E6%AD%A3%2C%20%E4%B8%8D%E6%98%AF%E6%B5%AA%E8%B4%B9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么是平方：两个线性效应相乘——每单位交易的楔子更高，同时被挤掉的单位更多。弹性同时出现在两处，无弹性税基「数量不太动」，三角形自然小，这与归宿课「无弹性端多担矩形」同时成立、互不冲突：矩形是转移，三角形是消失的互利。已有的扭曲会改账：市场上已有别的楔子时，单独缩小一个三角形可能放大别处的，加总只在第一最佳附近成立——<a href="/econ/theory-of-second-best">次优</a>的回声，Ramsey 课的边界在此重申。还有一类例外：矫正外部性的楔子挤掉的是负剩余活动，它的「三角形」是校正收益，不是浪费——下一课的主角。</p><p><span class="marginnote">行政与稽查成本不在三角形里：宽基低税省下的三角形，可能被申报复杂度吃回去。平方律只算价格扭曲这一漏，报告税改时要与合规成本分列。</span></p><p><span class="marginnote">常见误区：初学者容易把「无弹性端多担税」与「无弹性税基三角形小」看成矛盾。其实是两本账：归宿问的是矩形（转移）落在谁头上，效率问的是三角形（消失的互利）有多大——对香烟这类需求很缺弹性的税基，烟民几乎全额负担税负，同时被挤掉的交易也很少，两句话同时成立。</span></p>',4)),(E(),o(i,null,{default:e(()=>[A(r,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20LR%0A%20%20TUP%5B%22%E7%A8%8E%E7%8E%87%20t%20%E7%BF%BB%E5%80%8D%22%5D%20--%3E%20W1%5B%22%E6%AF%8F%E5%8D%95%E4%BD%8D%E6%A5%94%E5%AD%90%E5%8F%98%E5%AE%BD%E4%B8%80%E5%80%8D%22%5D%0A%20%20TUP%20--%3E%20W2%5B%22%E8%A2%AB%E6%8C%A4%E6%8E%89%E7%9A%84%E4%BA%A4%E6%98%93%E9%87%8F%20%CE%94q%20%E4%B9%9F%E7%BF%BB%E5%80%8D%22%5D%0A%20%20W1%20--%3E%20AREA%5B%22%E4%B8%89%E8%A7%92%E5%BD%A2%E9%9D%A2%E7%A7%AF%20%3D%20%C2%BD%20%C3%97%20%E6%A5%94%E5%AD%90%20%C3%97%20%E6%8C%A4%E6%8E%89%E9%87%8F%22%5D%0A%20%20W2%20--%3E%20AREA%0A%20%20AREA%20--%3E%20FOUR%5B%22%E6%8D%9F%E5%A4%B1%E7%BA%A6%E4%B8%BA%E5%8E%9F%E5%9B%9B%E5%80%8D%EF%BC%9A%E6%94%B6%E5%85%A5%E5%8F%AA%E7%BF%BB%E4%B8%80%E7%95%AA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收入效应大时 Marshall 三角不等于补偿变分，大税要换 EV/CV 口径；交叉价格与替代矩阵让「逐市场三角形」失真；储蓄、资本收益的三角形在跨期模型里另写，本课不展开。把 DWL 线性外推成「税率乘税率」以外的比例、或把两种楔子画进同一张福利账，是本课禁止的两类错。后课默认：先问楔子是不是矫正性的，再决定三角形记浪费还是记收益。</p><p><span class="marginnote">为什么大税要换口径：对瘾君子加烟草税，他口袋里的实际购买力被压低，需求曲线本身在动——量出来的三角形混进了「穷人变穷」的收入效应。补偿变分问的是「补他一笔钱让福利回到原水平，纯价格扭曲值多少」，这才把替代效应单独剥出来；小税两种算法差距可以忽略，大税不行。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DWL ≈ ½ t Δq；代入弹性得随 \\(t^2\\) 增长的平方律。</li><li>小税的伤害是二阶的：宽基低税率的效率算术全部来自平方律。</li><li>边际三角形随税率上升，边际公共资金由此有度量口径。</li><li>Ramsey 规则 = 各税基的边际三角形对边际收入拉平，逆弹性是其特解。</li><li>矫正性楔子的三角形记收益，为碳定价留口。</li><li>出处：Ramsey 1927；Harberger, AER 1964；主干无谓损失课。</li></ul>',5))])}const T=l(d,[["render",p]]);export{f as __pageData,T as default};
